def find(xs, wanted):
    for index, x in enumerate(xs):
        if x == wanted:
            return index
    return -1
print(find(["a", "b"], "b"), find([], 1), 1 < 2 < 3, 1 < 2 > 5, 3 > 2 >= 2 != 1)
